<section class="panel"><div class="heading-row"><h2>Your updates</h2><form action="<?= site_url('notifications/read') ?>" method="post"><?= csrf_field() ?><button class="secondary" type="submit">Mark all as read</button></form></div><?php if(!$notifications): ?><p>No notifications yet.</p><?php endif ?><?php foreach($notifications as $n): ?><article class="notice"><span class="badge"><?= $n['read_at']?'Read':'Unread' ?></span><p><?= esc($n['message']) ?></p><?php if($n['booking_id']): ?><a href="<?= site_url('bookings/'.$n['booking_id']) ?>">Open booking #<?= (int)$n['booking_id'] ?></a><?php endif ?><small><?= esc($n['created_at']) ?></small></article><?php endforeach ?></section>
